class Solution {
public:
    int memo[250][250][27];
    int solve(const string& s, int i, int j, int prev) {
        if (i >= j) return 0;
        if (memo[i][j][prev] != -1) return memo[i][j][prev];
        int ans = 0;
        int ci = s[i] - 'a' + 1;
        int cj = s[j] - 'a' + 1;
        if (ci == cj && ci != prev) {
            ans = solve(s, i + 1, j - 1, ci) + 2;
        } else {
            ans = max(solve(s, i + 1, j, prev), solve(s, i, j - 1, prev));
        }
        return memo[i][j][prev] = ans;
    }
    int longestPalindromeSubseq(string s) {
        memset(memo, -1, sizeof(memo));
        return solve(s, 0, s.size() - 1, 0);
    }
};

class Solution {
    private int[][][] memo;
    private int solve(String s, int i, int j, int prev) {
        if (i >= j) return 0;
        if (memo[i][j][prev] != -1) return memo[i][j][prev];
        int ans;
        int ci = s.charAt(i) - 'a' + 1;
        int cj = s.charAt(j) - 'a' + 1;
        if (ci == cj && ci != prev) {
            ans = solve(s, i + 1, j - 1, ci) + 2;
        } else {
            ans = Math.max(solve(s, i + 1, j, prev), solve(s, i, j - 1, prev));
        }
        return memo[i][j][prev] = ans;
    }
    public int longestPalindromeSubseq(String s) {
        int n = s.length();
        memo = new int[n][n][27];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }
        return solve(s, 0, n - 1, 0);
    }
}

var longestPalindromeSubseq = function(s) {
    const memo = new Map();
    function dp(i, j, prev) {
        if (i >= j) return 0;
        const key = (i << 14) | (j << 6) | prev;
        if (memo.has(key)) return memo.get(key);
        let ans = 0;
        const ci = s.charCodeAt(i) - 96;
        const cj = s.charCodeAt(j) - 96;
        if (ci === cj && ci !== prev) {
            ans = dp(i + 1, j - 1, ci) + 2;
        } else {
            ans = Math.max(dp(i + 1, j, prev), dp(i, j - 1, prev));
        }
        memo.set(key, ans);
        return ans;
    }
    return dp(0, s.length - 1, 0);
};
